43	  const count = sorted.length;
44	  const min = sorted[0];
45	  const max = sorted[count - 1];
46	  const mean = meanOf(sorted);
47	  const median = medianOfSorted(sorted);
48	  const p95 = p95OfSorted(sorted);
49	  const stddev = stddevPopulation(sorted, mean);
50	  return {
51	    count,
52	    min,
53	    max,
54	    mean: round6(mean),
55	    median: round6(median),
56	    p95,
57	    stddev: round6(stddev),
58	  };
59	}
