151	// 双侧 Welch t 检验：baseline 与 candidate 均为至少 2 个样本的数组。
152	// t 取候选减基线方向。返回保留六位小数的
153	// { t_statistic, degrees_of_freedom, p_value }。
154	// 两边方差均为 0 的退化情形：均值相同 -> {0, null, 1}；均值不同 -> {null, null, 0}。
155	function welchTest(baseline, candidate) {
156	  const n1 = baseline.length;
157	  const n2 = candidate.length;
158	  const m1 = meanOf(baseline);
159	  const m2 = meanOf(candidate);
160	  const v1 = sampleVariance(baseline, m1);
161	  const v2 = sampleVariance(candidate, m2);
162	
163	  if (v1 === 0 && v2 === 0) {
164	    if (m1 === m2) {
165	      return { t_statistic: 0, degrees_of_freedom: null, p_value: 1 };
166	    }
167	    return { t_statistic: null, degrees_of_freedom: null, p_value: 0 };
168	  }
169	
170	  const s1 = v1 / n1;
171	  const s2 = v2 / n2;
172	  const t = (m2 - m1) / Math.sqrt(s1 + s2);
173	  const df = (s1 + s2) ** 2 / (s1 ** 2 / (n1 - 1) + s2 ** 2 / (n2 - 1));
174	  const p = regularizedIncompleteBeta(df / (df + t * t), df / 2, 0.5);
175	  return {
176	    t_statistic: round6(t),
177	    degrees_of_freedom: round6(df),
178	    p_value: round6(p),
179	  };
180	}
181	
182	// 双侧配对 t 检验：deltas 为逐对候选减基线差值（至少 2 个）。
183	// t = mean / (sample_stddev / sqrt(count))，degrees_of_freedom = count - 1，
184	// p 与 welchTest 同一口径：I_{df/(df+t^2)}(df/2, 1/2)。
185	// 差值零方差的退化情形与 welchTest 一致：均值为 0 -> {0, null, 1}；
186	// 均值非 0 -> {null, null, 0}。
187	function pairedTTest(deltas) {
188	  const n = deltas.length;
189	  const m = meanOf(deltas);
190	  const v = sampleVariance(deltas, m);
191	
192	  if (v === 0) {
193	    if (m === 0) {
194	      return { t_statistic: 0, degrees_of_freedom: null, p_value: 1 };
195	    }
196	    return { t_statistic: null, degrees_of_freedom: null, p_value: 0 };
197	  }
198	
199	  const t = m / Math.sqrt(v / n);
200	  const df = n - 1;
201	  const p = regularizedIncompleteBeta(df / (df + t * t), df / 2, 0.5);
202	  return {
203	    t_statistic: round6(t),
204	    degrees_of_freedom: df,
205	    p_value: round6(p),
206	  };
207	}
208	
209	// 配对均值差（候选减基线）的双侧（1 - alpha）区间，内部原始（未取整）值。
210	// deltas 为至少 2 个逐对差值，0 < alpha < 1；baselineMean 为成对基线样本均值，
211	// 为 0 时两个百分比端点为 null。差值零方差时区间退化为单点（两端均为差值均值），
212	// 不反解临界值；与 welchMeanInterval 的退化口径一致。
213	function pairedMeanInterval(deltas, baselineMean, alpha) {
214	  const n = deltas.length;
215	  const m = meanOf(deltas);
216	  const v = sampleVariance(deltas, m);
217	
218	  let lower;
219	  let upper;
220	  if (v === 0) {
221	    lower = m;
222	    upper = m;
223	  } else {
224	    const margin = tCriticalValue(n - 1, alpha) * Math.sqrt(v / n);
225	    lower = m - margin;
226	    upper = m + margin;
227	  }
228	
229	  return {
230	    level: 1 - alpha,
231	    lower_ns: lower,
232	    upper_ns: upper,
233	    lower_percent: baselineMean === 0 ? null : (lower / baselineMean) * 100,
234	    upper_percent: baselineMean === 0 ? null : (upper / baselineMean) * 100,
235	  };
236	}
237	
238	// t 分布双侧尾概率：给定自由度 df 与 t >= 0，返回 P(|T| >= t)。
239	// 与 welchTest 的 p 值同一口径：I_{df/(df+t^2)}(df/2, 1/2)。
240	function tTwoTailedP(df, t) {
241	  return regularizedIncompleteBeta(df / (df + t * t), df / 2, 0.5);
242	}
243	
244	// 反解双侧临界值 t*（t* >= 0），使 tTwoTailedP(df, t*) = twoTailedP。
245	// t>=0 上双侧尾概率随 t 严格单调递减：先倍增找上界，再二分收敛。
246	// 调用方保证 df > 0、0 < twoTailedP < 1。
247	function tCriticalValue(df, twoTailedP) {
248	  let hi = 1;
249	  while (tTwoTailedP(df, hi) > twoTailedP) {
250	    hi *= 2;
251	  }
252	  let lo = 0;
253	  for (let i = 0; i < 200; i++) {
254	    const mid = (lo + hi) / 2;
255	    if (tTwoTailedP(df, mid) > twoTailedP) {
256	      lo = mid;
257	    } else {
258	      hi = mid;
259	    }
260	  }
261	  return (lo + hi) / 2;
262	}
263	
264	// 候选均值减基线均值差的双侧 Welch（1 - alpha）区间，内部原始（未取整）值。
265	// baseline 与 candidate 均为至少 2 个样本的数组，0 < alpha < 1。
266	// 返回 { level, lower_ns, upper_ns, lower_percent, upper_percent }；
267	// 基线均值为 0 时两个百分比端点为 null。
268	// 两边方差均为 0 的退化情形：区间退化为单点，两端均为候选减基线均值
269	// （均值相同即两端为 0），不反解临界值；welch 与 decision 仍走 welchTest 口径。
270	function welchMeanInterval(baseline, candidate, alpha) {
271	  const n1 = baseline.length;
272	  const n2 = candidate.length;
273	  const m1 = meanOf(baseline);
274	  const m2 = meanOf(candidate);
275	  const v1 = sampleVariance(baseline, m1);
276	  const v2 = sampleVariance(candidate, m2);
277	  const diff = m2 - m1;
278	
279	  let lower;
280	  let upper;
281	  if (v1 === 0 && v2 === 0) {
282	    lower = diff;
283	    upper = diff;
284	  } else {
285	    const s1 = v1 / n1;
286	    const s2 = v2 / n2;
287	    const standardError = Math.sqrt(s1 + s2);
288	    const df = (s1 + s2) ** 2 / (s1 ** 2 / (n1 - 1) + s2 ** 2 / (n2 - 1));
289	    const margin = tCriticalValue(df, alpha) * standardError;
290	    lower = diff - margin;
291	    upper = diff + margin;
292	  }
293	
294	  return {
295	    level: 1 - alpha,
296	    lower_ns: lower,
297	    upper_ns: upper,
298	    lower_percent: m1 === 0 ? null : (lower / m1) * 100,
299	    upper_percent: m1 === 0 ? null : (upper / m1) * 100,
300	  };
301	}
302	
303	module.exports = {
304	  computeSummary,
305	  round6,
306	  welchTest,
307	  pairedTTest,
308	  pairedMeanInterval,
309	  tCriticalValue,
310	  welchMeanInterval,
311	};
312

