231	  const dir = tempDir();
232	  const baseline = writeCollect(dir, 'base.json', [1, 2, 3]);
233	  const candidate = writeCollect(dir, 'cand.json', [4, 5, 6]);
234	  const run = (alpha) => {
235	    const out = path.join(dir, `a-${alpha}.json`);
236	    const rr = runCli(['--baseline', baseline, '--candidate', candidate,
237	      '--output', out, '--alpha', String(alpha)]);
238	    assert.equal(rr.status, 0, rr.stderr);
