// ---- Mann-Whitney U 双侧检验 ----
// 无第三方依赖。小样本（合并后 N <= MWU_EXACT_LIMIT）用精确置换分布
// （BigInt 子集秩和计数，天然支持并列 midrank）；大样本用含结校正的
// 正态近似（连续性校正 0.5）。

const MWU_EXACT_LIMIT = 40;

// 标准正态 CDF，Phi(z)；大样本 MWU 近似用。erf 取 A&S 7.1.26 近似。
function erfApprox(x) {
  const sign = x < 0 ? -1 : 1;
  const ax = Math.abs(x);
  const t = 1 / (1 + 0.3275911 * ax);
  const y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t
    - 0.284496736) * t + 0.254829592) * t * Math.exp(-ax * ax);
  return sign * y;
}

function normalCdf(z) {
  return 0.5 * (1 + erfApprox(z / Math.SQRT2));
}

// 合并样本的平均秩（1-based midrank），按升序返回与 values 同序的秩数组。
function averageRanks(values) {
  const n = values.length;
  const order = Array.from({ length: n }, (_, i) => i).sort((a, b) => values[a] - values[b]);
  const ranks = new Array(n);
  let i = 0;
  while (i < n) {
    let j = i;
    while (j + 1 < n && values[order[j + 1]] === values[order[i]]) j++;
    // 结占据位置 i+1..j+1，平均秩为 (i+1+j+1)/2
    const avg = (i + j + 2) / 2;
    for (let k = i; k <= j; k++) ranks[order[k]] = avg;
    i = j + 1;
  }
  return ranks;
}

// 双侧 Mann-Whitney U 检验：x、y 为观测值数组。
// 返回 { u, z }：u 为两个方向秩和统计量中较小者 min(U1, U2)，U1+U2=m*n；
// 大样本近似时附带 z（精确路径 z 为 null）；p_value 为双侧 p（原始未取整）。
function mannWhitneyUTwoSided(x, y) {
  const m = x.length;
  const n = y.length;
  const total = m + n;
  const values = x.concat(y);
  const ranks = averageRanks(values);
  const rankSumX = ranks.slice(0, m).reduce((acc, r) => acc + r, 0);
  const u1 = rankSumX - m * (m + 1) / 2;
  const u = Math.min(u1, m * n - u1);
  const mean = m * n / 2;

  // 结项 sum(t^3 - t)
  const sortedValues = values.slice().sort((a, b) => a - b);
  let tieTerm = 0;
  for (let i = 0; i < total;) {
    let j = i;
    while (j + 1 < total && sortedValues[j + 1] === sortedValues[i]) j++;
    const t = j - i + 1;
    if (t > 1) tieTerm += t ** 3 - t;
    i = j + 1;
  }
  const variance = (m * n / 12) * (total + 1 - tieTerm / (total * (total - 1)));

  if (total <= MWU_EXACT_LIMIT && variance > 0) {
    // 精确置换：秩乘 2 取整（midrank 可能为 x.5），dp[k][s] 为从全部秩中
    // 取 k 个、秩和（乘 2 后）恰为 s 的子集个数。
    const ranks2 = ranks.map((r) => Math.round(r * 2));
    const maxSum = m * 2 * (total + 1);
    let dp = Array.from({ length: m + 1 }, () => new BigInt64ArrayFallback(maxSum + 1));
    dp[0][0] = 1n;
    for (let idx = 0; idx < total; idx++) {
      const r2 = ranks2[idx];
      for (let k = Math.min(idx, m - 1); k >= 0; k--) {
        const layer = dp[k];
        const next = dp[k + 1];
        for (let s = maxSum - r2; s >= 0; s--) {
          if (layer[s] !== 0n) next[s + r2] += layer[s];
        }
      }
    }
    const observed = Math.abs(u1 - mean) * 2; // 乘 2 单位下观测到的偏离
    let favorable = 0n;
    let grand = 0n;
    const base = m * (m + 1); // sumR2 - m(m+1) = 2*U1
    for (let s = 0; s <= maxSum; s++) {
      const count = dp[m][s];
      if (count === 0n) continue;
      grand += count;
      if (Math.abs(s - base - m * n) >= observed) favorable += count;
    }
    return { u, z: null, p_value: Number(favorable) / Number(grand) };
  }

  if (variance === 0) {
    return { u, z: null, p_value: u1 === mean ? 1 : 0 };
  }

  const sd = Math.sqrt(variance);
  const z = Math.max(0, (Math.abs(u1 - mean) - 0.5)) / sd;
  return { u, z, p_value: Math.min(1, 2 * (1 - normalCdf(z))) };
}

// 普通 BigInt64Array 不能存任意精度 BigInt，用普通数组承载 BigInt 计数。
function BigInt64ArrayFallback(length) {
  return new Array(length).fill(0n);
}

// Holm（Holm–Bonferroni）逐步向下校正：m 个 p 升序后记 p_(1)<=...<=p_(m)，
// 调整值 q_(i) = min(1, max over j<=i ((m-j+1)*p_(j)))，映回原序，
// 保留六位小数。p 相同按原序稳定打破平局。
function holmAdjust(pValues) {
  const m = pValues.length;
  const order = Array.from({ length: m }, (_, i) => i)
    .sort((a, b) => (pValues[a] - pValues[b]) || (a - b));
  const adjusted = new Array(m);
  let running = 0;
  for (let rank = 1; rank <= m; rank++) {
    const index = order[rank - 1];
    running = Math.max(running, (m - rank + 1) * pValues[index]);
    adjusted[index] = round6(Math.min(1, running));
  }
  return adjusted;
}

module.exports = {
  computeSummary,
  round6,
  welchTest,
  pairedTTest,
  pairedMeanInterval,
  tCriticalValue,
  welchMeanInterval,
  mannWhitneyUTwoSided,
  holmAdjust,
};

