    ...groupSamples('build', 'b2', around(100, 5), around(100, 5)),
  ];
  const result = attributeRegression({ ...REGRESSION_REQUEST, samples });

  assert.equal(result.metric, 'duration_ns');
  assert.equal(result.comparison, 'cmp-1');
